contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function that checks ownership transfer behavior
    function run(address newOwner, address attacker) public payable {
        require(newOwner != address(0));
        // At deployment of C by the checker, this InvMutTest contract deployed c and is the owner.
        // Read owner before transfer
        address before = c.owner();

        // perform the ownership transfer from the rightful owner (this contract)
        c.transferOwnership(newOwner);
        address after = c.owner();

        // Now try an unauthorized transfer: simulate an attacker calling transferOwnership by using a low-level call from this contract
        // We craft calldata for transferOwnership(address) and call via the attacker's desired address encoded as the new owner.
        bytes memory sig = abi.encodeWithSignature("transferOwnership(address)", attacker);
        bool success;
        // low-level call: msg.sender remains this contract, so this will be an unauthorized attempt only if this contract is not owner anymore
        (success,) = address(c).call(sig);
        bool reverted = !success;

        // Assert the general rule:
        // - If the initial transfer succeeded, c.owner() must equal newOwner.
        // - If the low-level call reverted, owner must remain unchanged after that call (i.e., still newOwner if first succeeded, or before if first failed).
        address ownerAfterBoth = c.owner();
        assert((after == newOwner) && (ownerAfterBoth == after) && (reverted == (ownerAfterBoth == after ? (attacker != ownerAfterBoth) : true)));
    }

    receive() external payable { }
}

