contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters: callerWillBeOwner indicates whether this contract should act as owner by first ensuring it's owner;
    // newOwner is the address to set in the tested transfer; attacker is used to attempt a transfer when not owner.
    function run(address newOwner, address attacker, bool makeThisOwner) public payable {
        require(newOwner != address(0));

        // read initial owner
        address ownerBefore = c.owner();

        // If requested, make this contract the owner by calling transferOwnership on behalf of the current owner.
        // Since the freshly deployed c has owner == address(this) (the deployer of c is InvMutTest),
        // we only call transferOwnership to set owner to address(this) when needed by calling it from this contract.
        // To ensure this call is valid, only invoke it when ownerBefore == address(this) or when makeThisOwner is false.
        if (makeThisOwner) {
            // Only perform a state-changing transferOwnership if this contract is currently the owner.
            // If it's not, attempting to call would revert; we guard to ensure assert is reachable.
            if (ownerBefore == address(this)) {
                c.transferOwnership(address(this));
            }
        }

        // record owner after optional setup
        address ownerAfterSetup = c.owner();

        // Attempt transferOwnership from this contract to newOwner and observe revert behavior.
        bool callReverted;
        try c.transferOwnership(newOwner) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        address ownerAfterCall = c.owner();

        // Now attempt a transfer by attacker to attacker (to check non-owner cannot change owner).
        // We cannot impersonate attacker here, but we can reason: if this contract is not owner, then previous call should have reverted and owner unchanged.
        // General rule expressed as a relation between ownerBefore/ownerAfterSetup/callReverted/ownerAfterCall:
        // - If the call from this contract did not revert, then this contract must have been the owner before the call (ownerAfterSetup == address(this)) and ownerAfterCall == newOwner.
        // - If the call from this contract reverted, then ownerAfterCall == ownerAfterSetup (owner unchanged).
        assert(
            (callReverted && ownerAfterCall == ownerAfterSetup)
            || (!callReverted && ownerAfterSetup == address(this) && ownerAfterCall == newOwner)
        );
    }

    receive() external payable { }
}

