contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: candidate new owner and a boolean indicating whether to attempt calling owned()
    function run(address newOwner, bool callOwned) public payable {
        require(true);

        // Read the current owner before any state changes
        address ownerBefore = c.owner();

        // Attempt to transfer ownership from this contract to newOwner
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // After attempting transfer, read owner
        address ownerAfter = c.owner();

        // If transfer did not revert, ownership must have been set to newOwner
        // If transfer reverted, owner must remain ownerBefore
        bool transferOkImpliesOwnerChanged = (!transferReverted) ? (ownerAfter == newOwner) : (ownerAfter == ownerBefore);

        // Now optionally try calling owned() and record whether it reverts
        bool ownedReverted;
        if (callOwned) {
            try c.owned() {
                ownedReverted = false;
            } catch {
                ownedReverted = true;
            }
        } else {
            // if not called, set flag to false to avoid affecting invariant
            ownedReverted = false;
        }

        /* General rule asserted:
           - transferOwnership either succeeds and sets owner to newOwner, or it reverts and owner stays the same;
           - if owned() was called, it must revert exactly when this contract is not the current owner (i.e., msg.sender != owner).
           Note: when c.owned() is invoked from this contract, msg.sender for C is address(this), so compare ownerAfter to address(this).
        */
        assert(
            transferOkImpliesOwnerChanged &&
            (
                (!callOwned) || // if we didn't call owned, nothing to require about its revert
                (ownedReverted == (c.owner() != address(this)))
            )
        );
    }

    receive() external payable {}
}

